import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const u=JSON.parse('{"title":"脚本界面与积木知识索引","description":"","frontmatter":{},"headers":[],"relativePath":"脚本系统/脚本界面与积木知识索引.md","filePath":"脚本系统/脚本界面与积木知识索引.md","lastUpdated":1777893104000}'),h={name:"脚本系统/脚本界面与积木知识索引.md"};function d(o,l,c,n,t,p){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="脚本界面与积木知识索引" tabindex="-1">脚本界面与积木知识索引 <a class="header-anchor" href="#脚本界面与积木知识索引" aria-label="Permalink to “脚本界面与积木知识索引”">​</a></h1><ul><li>分类：脚本</li><li>子系统：脚本界面 / 组件 / 指令 / 作用域 / 流程控制</li><li>关键词标签：脚本界面, 积木系统, 自定义组件, 指令, 触发时机, 局部变量, 自身属性, 地图属性, 系统属性, 广播</li><li>来源类型：脚本界面截图</li><li>证据等级：截图直接证据 + 多来源交叉归纳</li><li>完整度状态：持续扩展中</li><li>版本号：4.56.18b27（截图可见版本为主）</li><li>来源文件：<code>docs/OCR资料/基础写脚本界面截图转文本.md</code></li><li>来源截图编号：215321, 215325, 215333, 215355, 215357, 215403, 215404, 215405, 215407, 215419, 215522, 215524, 215530~215538, 215547, 215554, 215557</li><li>最后更新：2026-04-20</li><li>适合查询：脚本界面长什么样、组件如何分类、自定义组件如何组织、变量作用域怎么分、常见积木有哪些</li></ul><p>本文件根据 <code>资料/基础写脚本界面截图/</code> 的截图 OCR 与人工归纳整理而成，目标是把脚本编辑界面、自定义组件界面、积木分类与典型脚本块能力转成可检索知识。</p><blockquote><p>说明：内容基于截图转文本与人工纠错，部分术语仍可能受 OCR 影响，后续可继续校对。</p></blockquote><h2 id="_1-组件分类结构" tabindex="-1">1. 组件分类结构 <a class="header-anchor" href="#_1-组件分类结构" aria-label="Permalink to “1. 组件分类结构”">​</a></h2><p>从组件添加界面截图可确认，创游世界的组件系统至少包含以下分类：</p><ul><li>通用</li><li>战斗</li><li>装置</li><li>显示</li><li>交互</li><li>自定义</li></ul><p>这说明组件体系并不是平铺列表，而是按功能域组织，便于按用途挂载能力。</p><h3 id="已识别的组件项" tabindex="-1">已识别的组件项 <a class="header-anchor" href="#已识别的组件项" aria-label="Permalink to “已识别的组件项”">​</a></h3><p>在“装置”相关组件截图中，可识别的组件包括：</p><ul><li>物理</li><li>可互动</li><li>开关</li><li>物体检测器</li><li>阻挡通行</li><li>等级</li><li>告示牌</li><li>物体 UI</li></ul><p>在“战斗”相关组件截图中，可识别的组件包括：</p><ul><li>生命</li><li>伤害</li><li>武器槽</li></ul><h3 id="知识意义" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义" aria-label="Permalink to “知识意义”">​</a></h3><ul><li>不同组件分类代表不同子系统能力。</li><li>战斗类更偏生命、伤害、武器等逻辑。</li><li>装置类更偏交互、检测、阻挡、物理与界面。</li><li>自定义类意味着创作者可自扩展组件能力。</li></ul><hr><h2 id="_2-自定义组件编辑结构" tabindex="-1">2. 自定义组件编辑结构 <a class="header-anchor" href="#_2-自定义组件编辑结构" aria-label="Permalink to “2. 自定义组件编辑结构”">​</a></h2><p>从多个截图可确认，自定义组件编辑器至少支持三类核心元素：</p><ul><li>属性</li><li>指令</li><li>触发时机</li></ul><h3 id="已识别界面元素" tabindex="-1">已识别界面元素 <a class="header-anchor" href="#已识别界面元素" aria-label="Permalink to “已识别界面元素”">​</a></h3><p>例如：</p><ul><li>组件名：<code>我的组件1</code></li><li>属性：<code>数字1</code>、<code>文本1</code></li><li>操作按钮： <ul><li><code>+添加属性</code></li><li><code>+添加指令</code></li><li><code>+添加触发时机</code></li></ul></li><li>底部功能： <ul><li><code>数据</code></li><li><code>保存</code></li><li><code>试玩</code></li></ul></li></ul><h3 id="知识意义-1" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义-1" aria-label="Permalink to “知识意义”">​</a></h3><p>这说明自定义组件不仅是“静态数据容器”，而是一个完整的可编程扩展单元，兼具：</p><ul><li>数据定义能力</li><li>行为入口定义能力</li><li>事件触发能力</li></ul><p>也就是说，自定义组件本质上很接近“带状态与行为的可复用模块”。</p><hr><h2 id="_3-自定义指令与触发时机" tabindex="-1">3. 自定义指令与触发时机 <a class="header-anchor" href="#_3-自定义指令与触发时机" aria-label="Permalink to “3. 自定义指令与触发时机”">​</a></h2><p>截图中多次出现如下结构：</p><ul><li><code>当执行“指令1”时</code></li><li><code>当执行“指令2”时</code></li></ul><p>这表明自定义组件中的“指令”可以作为一个可被调用的行为入口，而“当执行某指令时”则是其脚本实现区。</p><h3 id="已识别脚本能力" tabindex="-1">已识别脚本能力 <a class="header-anchor" href="#已识别脚本能力" aria-label="Permalink to “已识别脚本能力”">​</a></h3><p>在相关截图中可识别的行为包括：</p><ul><li>新建局部变量</li><li>设置局部变量</li><li>设置自身属性</li><li>设置当前地图属性</li><li>设置系统属性</li></ul><p>例如 OCR 中出现：</p><ul><li><code>新建局部变量 为 1</code></li><li><code>设置局部变量1为1</code></li><li><code>设置自身属性1为1</code></li><li><code>设置当前地图属性4为1</code></li><li><code>设置系统属性4为1</code></li></ul><h3 id="可提炼的结构理解" tabindex="-1">可提炼的结构理解 <a class="header-anchor" href="#可提炼的结构理解" aria-label="Permalink to “可提炼的结构理解”">​</a></h3><p>自定义指令脚本中至少涉及以下作用域：</p><ul><li>局部变量</li><li>自身属性</li><li>当前地图属性</li><li>系统属性</li></ul><h3 id="知识意义-2" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义-2" aria-label="Permalink to “知识意义”">​</a></h3><p>这说明脚本执行时不是单一变量空间，而是存在多层作用域：</p><ul><li>临时局部数据</li><li>组件/物体自身数据</li><li>地图级数据</li><li>系统级数据</li></ul><p>这对理解脚本块的数据流、读写范围和联机同步影响都很重要。</p><hr><h2 id="_4-常见基础动作类脚本块" tabindex="-1">4. 常见基础动作类脚本块 <a class="header-anchor" href="#_4-常见基础动作类脚本块" aria-label="Permalink to “4. 常见基础动作类脚本块”">​</a></h2><p>从脚本块选择界面截图中，已识别到一批动作/对象控制相关脚本块：</p><ul><li>父物体</li><li>子物体</li><li>播放动效</li><li>查找最近的角（可能是角色/目标，待进一步校对）</li><li>播放动画</li><li>停止动画</li><li>沿角度移动</li><li>以角度面向</li><li>销毁自身</li><li>触发/发送广播</li></ul><h3 id="可推测所属能力域" tabindex="-1">可推测所属能力域 <a class="header-anchor" href="#可推测所属能力域" aria-label="Permalink to “可推测所属能力域”">​</a></h3><p>这些脚本块主要覆盖：</p><ul><li>对象层级访问</li><li>动画播放控制</li><li>方向/朝向控制</li><li>物体销毁</li><li>广播通信</li></ul><h3 id="知识意义-3" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义-3" aria-label="Permalink to “知识意义”">​</a></h3><p>这说明创游脚本系统中，基础动作层已经覆盖了典型游戏对象操作闭环：</p><ul><li>找对象</li><li>控动画</li><li>改方向</li><li>改移动</li><li>销毁</li><li>发送事件</li></ul><hr><h2 id="_5-渐变-时间驱动脚本线索" tabindex="-1">5. 渐变 / 时间驱动脚本线索 <a class="header-anchor" href="#_5-渐变-时间驱动脚本线索" aria-label="Permalink to “5. 渐变 / 时间驱动脚本线索”">​</a></h2><p>截图 <code>Screenshot_20260417_215639.jpg</code> 中识别到近似文本：</p><ul><li><code>1秒将自身...</code></li><li><code>渐变至 1 并等待结束</code></li></ul><p>虽然 OCR 不完整，但能较明确地看出：</p><ul><li>存在时间型脚本块</li><li>存在渐变执行能力</li><li>存在“并等待结束”式同步流程控制</li></ul><h3 id="知识意义-4" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义-4" aria-label="Permalink to “知识意义”">​</a></h3><p>这类脚本块通常意味着：</p><ul><li>可做补间动画</li><li>可做属性平滑过渡</li><li>可把异步动画串入顺序逻辑</li></ul><p>这对 UI 动画、物体淡入淡出、移动缓动等都很关键。</p><hr><h2 id="_6-编辑器工作流特征" tabindex="-1">6. 编辑器工作流特征 <a class="header-anchor" href="#_6-编辑器工作流特征" aria-label="Permalink to “6. 编辑器工作流特征”">​</a></h2><p>从多个截图底部统一出现：</p><ul><li>数据</li><li>保存</li><li>试玩</li></ul><p>可推断脚本编辑器工作流强调：</p><ol><li>修改数据或脚本</li><li>保存</li><li>立即试玩验证</li></ol><h3 id="知识意义-5" tabindex="-1">知识意义 <a class="header-anchor" href="#知识意义-5" aria-label="Permalink to “知识意义”">​</a></h3><p>这与社区分析文档中“保存时可能生成脚本”的猜想可以互相印证：</p><ul><li>至少从交互设计上看，保存是非常核心的一步</li><li>试玩和保存耦合紧密，适合边改边测</li></ul><hr><h2 id="_7-当前可归纳的脚本系统结构" tabindex="-1">7. 当前可归纳的脚本系统结构 <a class="header-anchor" href="#_7-当前可归纳的脚本系统结构" aria-label="Permalink to “7. 当前可归纳的脚本系统结构”">​</a></h2><p>结合已有截图，可初步把脚本系统理解为以下几层：</p><h3 id="组件层" tabindex="-1">组件层 <a class="header-anchor" href="#组件层" aria-label="Permalink to “组件层”">​</a></h3><ul><li>内置组件</li><li>自定义组件</li></ul><h3 id="自定义扩展层" tabindex="-1">自定义扩展层 <a class="header-anchor" href="#自定义扩展层" aria-label="Permalink to “自定义扩展层”">​</a></h3><ul><li>属性</li><li>指令</li><li>触发时机</li></ul><h3 id="变量作用域层" tabindex="-1">变量作用域层 <a class="header-anchor" href="#变量作用域层" aria-label="Permalink to “变量作用域层”">​</a></h3><ul><li>局部变量</li><li>自身属性</li><li>地图属性</li><li>系统属性</li></ul><h3 id="执行动作层" tabindex="-1">执行动作层 <a class="header-anchor" href="#执行动作层" aria-label="Permalink to “执行动作层”">​</a></h3><ul><li>动画</li><li>动效</li><li>方向与移动</li><li>父子物体</li><li>广播</li><li>销毁</li><li>渐变</li></ul><hr><h2 id="_8-适合-ai-rag-的关键词" tabindex="-1">8. 适合 AI/RAG 的关键词 <a class="header-anchor" href="#_8-适合-ai-rag-的关键词" aria-label="Permalink to “8. 适合 AI/RAG 的关键词”">​</a></h2><ul><li>脚本界面</li><li>积木系统</li><li>自定义组件</li><li>添加属性</li><li>添加指令</li><li>添加触发时机</li><li>当执行某指令时</li><li>局部变量</li><li>自身属性</li><li>当前地图属性</li><li>系统属性</li><li>播放动画</li><li>停止动画</li><li>沿角度移动</li><li>以角度面向</li><li>销毁自身</li><li>广播</li><li>渐变</li><li>等待结束</li></ul><hr><h2 id="_9-对知识库建设的建议" tabindex="-1">9. 对知识库建设的建议 <a class="header-anchor" href="#_9-对知识库建设的建议" aria-label="Permalink to “9. 对知识库建设的建议”">​</a></h2><p>建议后续把 <code>资料/基础写脚本界面截图/</code> 继续拆成以下专题：</p><ol><li>组件添加界面专题</li><li>自定义组件专题</li><li>指令与触发时机专题</li><li>变量作用域专题</li><li>动画与动作脚本块专题</li><li>广播与事件脚本块专题</li><li>渐变与时间控制脚本块专题</li></ol><p>这样更适合后续：</p><ul><li>问答检索</li><li>教学整理</li><li>脚本能力盘点</li><li>与引擎版本变动做交叉索引</li></ul>',92)])])}const b=i(h,[["render",d]]);export{u as __pageData,b as default};
